import json
from collections import Counter
c=Counter(); paths=[]
for l in open(\"/home/fedora/attack-file-events.json\"):
    try: e=json.loads(l)
    except: continue
    for k in (\"process_kprobe\",\"process_lsm\"):
        if k in e:
            p=e[k]; c[p.get(\"policy_name\",\"?\")]+=1
            if k==\"process_lsm\":
                for a in p.get(\"args\",[]):
                    if \"file_arg\" in a: paths.append(a[\"file_arg\"][\"path\"])
print(\"ATTACK_POLICY_ALERTS\",dict(c))
print(\"LSM_PATHS\",sorted(set(paths)))
""

